CREATE TABLE IF NOT EXISTS recipe_ingredients (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), recipe_id UUID NOT NULL REFERENCES recipes(id) ON DELETE CASCADE, food_id UUID REFERENCES food_catalog(id) ON DELETE SET NULL, food_name TEXT NOT NULL, quantity NUMERIC NOT NULL CHECK (quantity > 0), grams NUMERIC NOT NULL DEFAULT 0, calories NUMERIC NOT NULL DEFAULT 0, protein NUMERIC NOT NULL DEFAULT 0, carbs NUMERIC NOT NULL DEFAULT 0, fat NUMERIC NOT NULL DEFAULT 0, fiber NUMERIC NOT NULL DEFAULT 0);